public int distSquared(Point other) {
    int dx = x - other.getX();
    int dy = y - other.getY();
    return dx * dx + dy * dy;
}

public static int closest(Point[] arr) {
    int best = arr[0].distSquared(arr[1]);
    for (int i = 0; i < arr.length; i++) {
        for (int j = i + 1; j < arr.length; j++) {
            int d = arr[i].distSquared(arr[j]);
            if (d < best) {
                best = d;
            }
        }
    }
    return best;
}

